type productionLeaseHashPayload struct { LeaseID string `json:"lease_id"`; LeaseVersion string `json:"lease_version"`; PolicyVersion string `json:"policy_version"`; ApprovalRef string `json:"approval_ref"`; ReviewedBy string `json:"reviewed_by"`; ReviewerID string `json:"reviewer_id"`; ReviewedAt string `json:"reviewed_at"`; PromotionReviewRef string `json:"promotion_review_ref"`; SourceCanaryGrantID string `json:"source_canary_grant_id"`; SourceCanaryGrantVersion string `json:"source_canary_grant_version"`; SourceCanaryGrantHash string `json:"source_canary_grant_hash"`; ValidFrom string `json:"valid_from"`; ExpiresAt string `json:"expires_at"`; AllowedRiskClasses []string `json:"allowed_risk_classes"`; AllowedActionTypes []string `json:"allowed_action_types"`; AllowedHosts []string `json:"allowed_hosts"`; ExecutorIDs []string `json:"executor_ids"`; MaxExecutionsTotal int `json:"max_executions_total"`; MaxExecutionsPerWindow int `json:"max_executions_per_window"`; WindowSeconds int `json:"window_seconds"`; MaxCostMinorTotal int64 `json:"max_cost_minor_total"`; Currency string `json:"currency"`; MaxPendingOutcomes int `json:"max_pending_outcomes"`; MaxConsecutiveFailures int `json:"max_consecutive_failures"`; MaxOutcomeAgeSeconds int `json:"max_outcome_age_seconds"`; MaxHealthSnapshotAgeSeconds int `json:"max_health_snapshot_age_seconds"`; KillSwitchRequired bool `json:"kill_switch_required"`; CorrelationID string `json:"correlation_id"`; HashVersion string `json:"hash_version"` }
type healthHashPayload struct { SnapshotID string `json:"snapshot_id"`; LeaseID string `json:"lease_id"`; LeaseVersion string `json:"lease_version"`; LeaseHash string `json:"lease_hash"`; ObservedAt string `json:"observed_at"`; SourceRefs []string `json:"source_refs"`; DependencyState string `json:"dependency_state"`; TelemetryComplete bool `json:"telemetry_complete"`; ConsecutiveFailures int `json:"consecutive_failures"`; ReconciliationRequired bool `json:"reconciliation_required"`; ComplianceAlertCount int `json:"compliance_alert_count"`; OldestPendingOutcomeAgeSeconds int `json:"oldest_pending_outcome_age_seconds"`; HashVersion string `json:"hash_version"` }

func ComputeProductionLeaseHash(x ProductionLease) string { p:=productionLeaseHashPayload{LeaseID:x.LeaseID,LeaseVersion:x.LeaseVersion,PolicyVersion:x.PolicyVersion,ApprovalRef:x.ApprovalRef,ReviewedBy:x.ReviewedBy,ReviewerID:x.ReviewerID,ReviewedAt:x.ReviewedAt,PromotionReviewRef:x.PromotionReviewRef,SourceCanaryGrantID:x.SourceCanaryGrantID,SourceCanaryGrantVersion:x.SourceCanaryGrantVersion,SourceCanaryGrantHash:x.SourceCanaryGrantHash,ValidFrom:x.ValidFrom,ExpiresAt:x.ExpiresAt,AllowedRiskClasses:sortedCopy(x.AllowedRiskClasses),AllowedActionTypes:sortedCopy(x.AllowedActionTypes),AllowedHosts:sortedCopy(x.AllowedHosts),ExecutorIDs:sortedCopy(x.ExecutorIDs),MaxExecutionsTotal:x.MaxExecutionsTotal,MaxExecutionsPerWindow:x.MaxExecutionsPerWindow,WindowSeconds:x.WindowSeconds,MaxCostMinorTotal:x.MaxCostMinorTotal,Currency:x.Currency,MaxPendingOutcomes:x.MaxPendingOutcomes,MaxConsecutiveFailures:x.MaxConsecutiveFailures,MaxOutcomeAgeSeconds:x.MaxOutcomeAgeSeconds,MaxHealthSnapshotAgeSeconds:x.MaxHealthSnapshotAgeSeconds,KillSwitchRequired:x.KillSwitchRequired,CorrelationID:x.CorrelationID,HashVersion:x.HashVersion}; b,e:=json.Marshal(p);if e!=nil{return ""};s:=sha256.Sum256(b);return "sha256:"+hex.EncodeToString(s[:]) }
func SealProductionLease(x ProductionLease) ProductionLease { if x.HashVersion==""{x.HashVersion="go-json-v1"};x.Currency=strings.ToUpper(strings.TrimSpace(x.Currency));x.LeaseHash=ComputeProductionLeaseHash(x);return x }
func ComputeProductionHealthHash(x ProductionHealthSnapshot) string { refs:=append([]string(nil),x.SourceRefs...);sort.Strings(refs);p:=healthHashPayload{SnapshotID:x.SnapshotID,LeaseID:x.LeaseID,LeaseVersion:x.LeaseVersion,LeaseHash:x.LeaseHash,ObservedAt:x.ObservedAt,SourceRefs:refs,DependencyState:x.DependencyState,TelemetryComplete:x.TelemetryComplete,ConsecutiveFailures:x.ConsecutiveFailures,ReconciliationRequired:x.ReconciliationRequired,ComplianceAlertCount:x.ComplianceAlertCount,OldestPendingOutcomeAgeSeconds:x.OldestPendingOutcomeAgeSeconds,HashVersion:x.HashVersion};b,e:=json.Marshal(p);if e!=nil{return ""};s:=sha256.Sum256(b);return "sha256:"+hex.EncodeToString(s[:]) }
func SealProductionHealth(x ProductionHealthSnapshot) ProductionHealthSnapshot { if x.HashVersion==""{x.HashVersion="go-json-v1"};x.SnapshotHash=ComputeProductionHealthHash(x);return x }
func normalizedProductionLedger(l ProductionLedger, lease ProductionLease, now time.Time)(ProductionLedger,bool){if l.LeaseID!=lease.LeaseID||l.LeaseVersion!=lease.LeaseVersion||l.LeaseHash!=lease.LeaseHash||l.ExecutionsTotal<0||l.ExecutionsInWindow<0||l.CostMinorTotal<0||l.PendingOutcomes<0||l.PendingOutcomes!=len(l.PendingExecutionIDs)||l.ConsecutiveFailures<0{return l,false};s,e:=time.Parse(time.RFC3339,l.WindowStartedAt);if e!=nil||now.Before(s){return l,false};if now.Sub(s)>=time.Duration(lease.WindowSeconds)*time.Second{l.WindowStartedAt=now.Format(time.RFC3339);l.ExecutionsInWindow=0};return l,true}
func productionGate(state M11State,ctx M11Context)ProductionGateDecision{return ProductionGateDecision{GateID:"prod-gate-"+state.Lease.LeaseID+"-"+state.Intent.IntentID,LeaseID:state.Lease.LeaseID,LeaseVersion:state.Lease.LeaseVersion,LeaseHash:state.Lease.LeaseHash,IntentID:state.Intent.IntentID,IntentHash:state.Intent.IntentHash,PolicyVersion:state.Policy.PolicyVersion,RiskClass:state.Policy.RiskClass,HealthSnapshotID:state.Health.SnapshotID,HealthSnapshotHash:state.Health.SnapshotHash,CostBoundID:state.CostBound.CostBoundID,CostBoundHash:state.CostBound.CostBoundHash,CostBoundMinor:state.CostBound.MaxCostMinor,Decision:"DENY",Reason:"INVALID_PRODUCTION_STATE",EvaluatedAt:ctx.Now,ExecutionsTotalBefore:state.Ledger.ExecutionsTotal,ExecutionsInWindowBefore:state.Ledger.ExecutionsInWindow,CostMinorTotalBefore:state.Ledger.CostMinorTotal,PendingOutcomesBefore:state.Ledger.PendingOutcomes,ExecutionAuthorized:false}}
func productionRequireApproval(g *ProductionGateDecision,r string)ProductionGateDecision{g.Decision="REQUIRE_APPROVAL";g.Reason=r;return *g}
func productionStop(g *ProductionGateDecision,r string)ProductionGateDecision{g.Decision="STOP";g.Reason=r;return *g}
func productionDegrade(g *ProductionGateDecision,r string)ProductionGateDecision{g.Decision="DEGRADE";g.Reason=r;return *g}

func EvaluateProductionGate(state M11State,ctx M11Context)ProductionGateDecision{
	g:=productionGate(state,ctx);i,p,l,h,c:=state.Intent,state.Policy,state.Lease,state.Health,state.CostBound
	if i.IntentHash==""||i.IntentHash!=ComputeShadowIntentHash(i)||!i.ShadowOnly||!i.DryRun{g.Reason="INVALID_INTENT_BINDING";return g}
	if l.HashVersion!="go-json-v1"||l.LeaseHash==""||l.LeaseHash!=ComputeProductionLeaseHash(l){g.Reason="TAMPERED_LEASE";return g}
	if l.ReviewedBy!="human"||strings.TrimSpace(l.ReviewerID)==""||strings.TrimSpace(l.ApprovalRef)==""||strings.TrimSpace(l.PromotionReviewRef)==""||!l.KillSwitchRequired||l.MaxExecutionsTotal<1||l.MaxExecutionsPerWindow<1||l.MaxExecutionsPerWindow>l.MaxExecutionsTotal||l.WindowSeconds<60||l.MaxCostMinorTotal<0||l.MaxPendingOutcomes<1||l.MaxConsecutiveFailures<1||l.MaxOutcomeAgeSeconds<60||l.MaxHealthSnapshotAgeSeconds<60||len(l.AllowedRiskClasses)==0||len(l.AllowedActionTypes)==0||len(l.AllowedHosts)==0||len(l.ExecutorIDs)==0||hasWildcard(l.AllowedActionTypes)||hasWildcard(l.AllowedHosts)||hasWildcard(l.ExecutorIDs){g.Reason="INVALID_LEASE";return g}
	for _,r:=range l.AllowedRiskClasses{if r!="RISK0"&&r!="RISK1"{g.Reason="INVALID_LEASE";return g}}
	if ctx.ApprovedLeaseHashes==nil||ctx.PromotionValidatedRisks==nil||ctx.TrustedHealthSnapshots==nil||ctx.TrustedCostBounds==nil{g.Reason="GOVERNANCE_INPUTS_UNAVAILABLE";return g}
	ah,ok:=ctx.ApprovedLeaseHashes[l.ApprovalRef];if !ok{g.Reason="LEASE_PROVENANCE_MISSING";return g};if ah!=l.LeaseHash{g.Reason="LEASE_APPROVAL_MISMATCH";return g}
	validated,ok:=ctx.PromotionValidatedRisks[l.PromotionReviewRef];if !ok{g.Reason="PROMOTION_REVIEW_MISSING";return g}
	if containsFold(ctx.RevokedLeaseIDs,l.LeaseID){return productionStop(&g,"LEASE_REVOKED")};if ctx.KillSwitch{return productionStop(&g,"KILL_SWITCH_ACTIVE")}
	now,en:=time.Parse(time.RFC3339,ctx.Now);rv,er:=time.Parse(time.RFC3339,l.ReviewedAt);vf,ev:=time.Parse(time.RFC3339,l.ValidFrom);ex,ee:=time.Parse(time.RFC3339,l.ExpiresAt);if en!=nil||er!=nil||ev!=nil||ee!=nil||rv.After(vf)||!ex.After(vf){g.Reason="INVALID_LEASE_TIME";return g};if now.Before(vf){g.Decision="WAIT";g.Reason="LEASE_NOT_YET_ACTIVE";return g};if !ex.After(now){return productionRequireApproval(&g,"LEASE_EXPIRED")}
	pc,ep:=time.Parse(time.RFC3339,p.PolicyCheckedAt);if ep!=nil||pc.After(now)||p.PolicyVersion==""||p.IntentID!=i.IntentID||p.IntentHash!=i.IntentHash||!p.ShadowOnly||p.ExecutionAuthorized{g.Reason="INVALID_POLICY_STATE";return g};freshCtx:=ctx.PolicyContext;freshCtx.Now=ctx.Now;fresh:=EvaluateShadowPolicy(i,freshCtx);if fresh.Reason=="POLICY_UNAVAILABLE"||!policyEquivalentForExecution(p,fresh){g.Reason="POLICY_REVALIDATION_FAILED";return g};g.RiskClass=fresh.RiskClass;g.PolicyVersion=fresh.PolicyVersion;if l.PolicyVersion!=fresh.PolicyVersion{g.Reason="LEASE_POLICY_MISMATCH";return g}
	if fresh.RiskClass=="RISK2"{return productionRequireApproval(&g,"RISK2_PER_ACTION_APPROVAL_REQUIRED")};if fresh.RiskClass!="RISK0"&&fresh.RiskClass!="RISK1"{g.Reason="UNKNOWN_RISK_CLASS";return g};if fresh.RiskClass=="RISK0"&&fresh.Decision!="ALLOW"{g.Reason="POLICY_STATE_NOT_PRODUCTION_ELIGIBLE";return g};if fresh.RiskClass=="RISK1"&&(fresh.Decision!="HUMAN_REVIEW"||fresh.Reason!="RISK1_REQUIRES_REVIEW"){g.Reason="POLICY_STATE_NOT_PRODUCTION_ELIGIBLE";return g};if fresh.RiskClass=="RISK1"&&!containsFold(validated,"RISK1"){g.Reason="PROMOTION_RISK_NOT_VALIDATED";return g};if !containsFold(l.AllowedRiskClasses,fresh.RiskClass){return productionRequireApproval(&g,"RISK_NOT_DELEGATED")};if !containsFold(l.AllowedActionTypes,i.ActionType)||!allowedHost(i.Target,l.AllowedHosts){return productionRequireApproval(&g,"SCOPE_NOT_DELEGATED")};if !containsFold(l.ExecutorIDs,ctx.Executor.ExecutorID)||!containsFold(ctx.AllowedExecutorIDs,ctx.Executor.ExecutorID)||!executorAllows(ctx.Executor,i){g.Reason="EXECUTOR_NOT_ALLOWED";return g}
	if h.HashVersion!="go-json-v1"||h.SnapshotHash==""||h.SnapshotHash!=ComputeProductionHealthHash(h){g.Reason="TAMPERED_HEALTH";return g};if h.LeaseID!=l.LeaseID||h.LeaseVersion!=l.LeaseVersion||h.LeaseHash!=l.LeaseHash||len(h.SourceRefs)==0{g.Reason="HEALTH_MISMATCH";return g};th,ok:=ctx.TrustedHealthSnapshots[h.SnapshotID];if !ok||th!=h.SnapshotHash{g.Reason="HEALTH_UNTRUSTED";return g};ho,eh:=time.Parse(time.RFC3339,h.ObservedAt);if eh!=nil||ho.After(now){g.Reason="HEALTH_TIME_INVALID";return g};if now.Sub(ho)>time.Duration(l.MaxHealthSnapshotAgeSeconds)*time.Second{return productionDegrade(&g,"HEALTH_STALE")};if !h.TelemetryComplete{return productionDegrade(&g,"TELEMETRY_INCOMPLETE")};if h.DependencyState!="HEALTHY"{return productionDegrade(&g,"DEPENDENCY_DEGRADED")};if h.ComplianceAlertCount>0{return productionStop(&g,"COMPLIANCE_ALERT")};if h.ReconciliationRequired{return productionStop(&g,"RECONCILIATION_REQUIRED")};if h.ConsecutiveFailures>=l.MaxConsecutiveFailures{return productionStop(&g,"FAILURE_THRESHOLD")};if h.OldestPendingOutcomeAgeSeconds>l.MaxOutcomeAgeSeconds{return productionStop(&g,"OUTCOME_STALE")}
	if strings.TrimSpace(c.CostBoundID)==""{g.Reason="COST_BOUND_MISSING";return g};if c.HashVersion!="go-json-v1"||c.CostBoundHash==""||c.CostBoundHash!=ComputeCanaryCostBoundHash(c){g.Reason="TAMPERED_COST_BOUND";return g};if c.IntentID!=i.IntentID||c.IntentHash!=i.IntentHash||c.CorrelationID!=i.CorrelationID||c.MaxCostMinor<0||c.Currency!=l.Currency||strings.TrimSpace(c.SourceRef)==""{g.Reason="COST_BOUND_MISMATCH";return g};tc,ok:=ctx.TrustedCostBounds[c.CostBoundID];if !ok||tc!=c.CostBoundHash{g.Reason="COST_BOUND_UNTRUSTED";return g};co,eco:=time.Parse(time.RFC3339,c.ObservedAt);ce,ece:=time.Parse(time.RFC3339,c.ExpiresAt);if eco!=nil||ece!=nil||co.After(now)||!ce.After(co)||!ce.After(now){g.Reason="COST_BOUND_EXPIRED";return g}
	ledger,ok:=normalizedProductionLedger(state.Ledger,l,now);if !ok{g.Reason="LEDGER_MISMATCH";return g};g.ExecutionsTotalBefore=ledger.ExecutionsTotal;g.ExecutionsInWindowBefore=ledger.ExecutionsInWindow;g.CostMinorTotalBefore=ledger.CostMinorTotal;g.PendingOutcomesBefore=ledger.PendingOutcomes;if ledger.ControlMode=="STOPPED"{return productionStop(&g,"STICKY_STOP")};if ledger.ReconciliationRequired{return productionStop(&g,"RECONCILIATION_REQUIRED")};if ledger.ConsecutiveFailures>=l.MaxConsecutiveFailures{return productionStop(&g,"FAILURE_THRESHOLD")};if containsFold(ledger.SuccessfulIdempotencyKeys,i.IdempotencyKey){g.Decision="WAIT";g.Reason="DUPLICATE_EXECUTION";return g};if ledger.ExecutionsTotal>=l.MaxExecutionsTotal{return productionRequireApproval(&g,"PRODUCTION_TOTAL_BUDGET_EXHAUSTED")};if ledger.ExecutionsInWindow>=l.MaxExecutionsPerWindow{g.Decision="WAIT";g.Reason="RATE_LIMIT_REACHED";return g};if ledger.CostMinorTotal+c.MaxCostMinor>l.MaxCostMinorTotal{return productionRequireApproval(&g,"PRODUCTION_COST_BUDGET_EXHAUSTED")};if ledger.PendingOutcomes>=l.MaxPendingOutcomes{g.Decision="WAIT";g.Reason="OUTCOME_BACKPRESSURE";return g};g.CostBoundID=c.CostBoundID;g.CostBoundHash=c.CostBoundHash;g.CostBoundMinor=c.MaxCostMinor;g.Decision="ALLOW_PRODUCTION";g.Reason="PRODUCTION_ELIGIBLE";return g
}

func AuthorizeProduction(state M11State,ctx M11Context)(ProductionExecutionAuthorization,ProductionGateDecision,string){g:=EvaluateProductionGate(state,ctx);if g.Decision!="ALLOW_PRODUCTION"{return ProductionExecutionAuthorization{},g,g.Decision};now,_:=time.Parse(time.RFC3339,ctx.Now);ie,_:=time.Parse(time.RFC3339,state.Intent.ExpiresAt);le,_:=time.Parse(time.RFC3339,state.Lease.ExpiresAt);ce,_:=time.Parse(time.RFC3339,state.CostBound.ExpiresAt);he:=now.Add(time.Duration(state.Lease.MaxHealthSnapshotAgeSeconds)*time.Second);exp:=minTime(minTime(ie,le),minTime(ce,he));a:=ProductionExecutionAuthorization{AuthorizationID:"prod-auth-"+state.Lease.LeaseID+"-"+state.Intent.IntentID,IntentID:state.Intent.IntentID,IntentHash:state.Intent.IntentHash,PolicyVersion:state.Policy.PolicyVersion,ProductionLeaseID:state.Lease.LeaseID,ProductionLeaseVersion:state.Lease.LeaseVersion,ProductionLeaseHash:state.Lease.LeaseHash,ProductionGateID:g.GateID,ProductionHealthSnapshotID:state.Health.SnapshotID,ProductionHealthSnapshotHash:state.Health.SnapshotHash,ProductionCostBoundID:state.CostBound.CostBoundID,ProductionCostBoundHash:state.CostBound.CostBoundHash,ProductionCostBoundMinor:state.CostBound.MaxCostMinor,ExecutorID:ctx.Executor.ExecutorID,AuthorizedAt:ctx.Now,ExpiresAt:exp.Format(time.RFC3339),IdempotencyKey:state.Intent.IdempotencyKey,CorrelationID:state.Intent.CorrelationID,ExecutionMode:"GOVERNED_PRODUCTION",ExecutionAuthorized:true};return a,g,"AUTHORIZED"}
func productionLedgerPath(dir,id,ver string)string{s:=sha256.Sum256([]byte("production\x00"+id+"\x00"+ver));return filepath.Join(dir,"production-ledger-"+hex.EncodeToString(s[:])+".json")}
func productionLockPath(dir,id,ver string)string{s:=sha256.Sum256([]byte("production-lock\x00"+id+"\x00"+ver));return filepath.Join(dir,"production-lock-"+hex.EncodeToString(s[:]))}
func persistProductionLedger(path string,l ProductionLedger)error{b,e:=json.MarshalIndent(l,"","  ");if e!=nil{return e};tmp:=path+".tmp";if e=os.WriteFile(tmp,b,0600);e!=nil{return e};return os.Rename(tmp,path)}
func loadProductionLedger(path string)(ProductionLedger,error){var l ProductionLedger;b,e:=os.ReadFile(path);if e!=nil{return l,e};e=json.Unmarshal(b,&l);return l,e}
func ensureInitialProductionLedger(path string,l ProductionLedger)error{b,e:=json.MarshalIndent(l,"","  ");if e!=nil{return e};f,e:=os.OpenFile(path,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{return e};if _,e=f.Write(b);e!=nil{_ = f.Close();return e};if e=f.Sync();e!=nil{_ = f.Close();return e};return f.Close()}
func persistStickyStop(path string,state *M11State,reason,now string){state.Ledger.ControlMode="STOPPED";state.Ledger.StopReason=reason;state.Ledger.UpdatedAt=now;_ = persistProductionLedger(path,state.Ledger)}
func productionExecutionRecord(state M11State,a ProductionExecutionAuthorization,now,status,effect,ref,msg string)ProductionExecutionRecord{return ProductionExecutionRecord{ExecutionID:"exec-"+a.AuthorizationID,AuthorizationID:a.AuthorizationID,ProductionLeaseID:a.ProductionLeaseID,ProductionLeaseVersion:a.ProductionLeaseVersion,ProductionLeaseHash:a.ProductionLeaseHash,ProductionGateID:a.ProductionGateID,ProductionHealthSnapshotID:a.ProductionHealthSnapshotID,ProductionHealthSnapshotHash:a.ProductionHealthSnapshotHash,ProductionCostBoundID:a.ProductionCostBoundID,ProductionCostBoundHash:a.ProductionCostBoundHash,ProductionCostBoundMinor:a.ProductionCostBoundMinor,IntentID:a.IntentID,IntentHash:a.IntentHash,ExecutorID:a.ExecutorID,IdempotencyKey:a.IdempotencyKey,AttemptedAt:now,Status:status,SideEffectState:effect,ExternalRef:ref,Error:msg,CorrelationID:state.Intent.CorrelationID}}

func ExecuteProductionLocalSandbox(state *M11State,a ProductionExecutionAuthorization,ctx M11Context,dir string)(ProductionExecutionRecord,string){if state==nil||state.Authorization==nil||*state.Authorization!=a||!a.ExecutionAuthorized||a.ExecutionMode!="GOVERNED_PRODUCTION"{return ProductionExecutionRecord{},"DENY_AUTHORIZATION"};if e:=os.MkdirAll(dir,0755);e!=nil{return ProductionExecutionRecord{},"EXECUTION_FAILED"};lp:=productionLockPath(dir,state.Lease.LeaseID,state.Lease.LeaseVersion);lock,e:=os.OpenFile(lp,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{if os.IsExist(e){return ProductionExecutionRecord{},"WAIT_PRODUCTION_LOCK"};return ProductionExecutionRecord{},"EXECUTION_FAILED"};_ = lock.Close();defer os.Remove(lp);p:=productionLedgerPath(dir,state.Lease.LeaseID,state.Lease.LeaseVersion);ledger,e:=loadProductionLedger(p);if os.IsNotExist(e){if state.Ledger.ExecutionsTotal!=0||state.Ledger.ExecutionsInWindow!=0||state.Ledger.CostMinorTotal!=0||state.Ledger.PendingOutcomes!=0||len(state.Ledger.SuccessfulIdempotencyKeys)!=0||len(state.Ledger.PendingExecutionIDs)!=0||len(state.Ledger.OutcomeLinks)!=0||state.Ledger.ReconciliationRequired||state.Ledger.ControlMode=="STOPPED"{return ProductionExecutionRecord{},"WAIT_LEDGER_MISSING"};if e=ensureInitialProductionLedger(p,state.Ledger);e!=nil{return ProductionExecutionRecord{},"WAIT_RECONCILIATION"};ledger=state.Ledger}else if e!=nil{return ProductionExecutionRecord{},"WAIT_RECONCILIATION"};state.Ledger=ledger;expected,g,status:=AuthorizeProduction(*state,ctx);if status!="AUTHORIZED"{if g.Decision=="STOP"{persistStickyStop(p,state,g.Reason,ctx.Now)};return ProductionExecutionRecord{},status};if expected!=a{return ProductionExecutionRecord{},"DENY_AUTHORIZATION"};now,en:=time.Parse(time.RFC3339,ctx.Now);at,ea:=time.Parse(time.RFC3339,a.AuthorizedAt);ex,ee:=time.Parse(time.RFC3339,a.ExpiresAt);if en!=nil||ea!=nil||ee!=nil||at.After(now)||!ex.After(now){return ProductionExecutionRecord{},"DENY_EXPIRED_AUTHORIZATION"};marker:=sandboxIdempotencyPath(dir,a.IdempotencyKey);if _,e=os.Stat(marker);e==nil{if containsFold(state.Ledger.SuccessfulIdempotencyKeys,a.IdempotencyKey){return ProductionExecutionRecord{},"WAIT_ALREADY_EXECUTED"};state.Ledger.ReconciliationRequired=true;persistStickyStop(p,state,"RECONCILIATION_REQUIRED",ctx.Now);rec:=productionExecutionRecord(*state,a,ctx.Now,"RECONCILIATION_REQUIRED","UNKNOWN",marker,"idempotency marker exists without durable successful ledger entry");state.Execution=&rec;return rec,"STOP_RECONCILIATION"}else if !os.IsNotExist(e){return ProductionExecutionRecord{},"WAIT_RECONCILIATION"};payload:=map[string]any{"intent_id":state.Intent.IntentID,"intent_hash":state.Intent.IntentHash,"action_type":state.Intent.ActionType,"target":state.Intent.Target,"parameters":state.Intent.Parameters,"production_lease_id":a.ProductionLeaseID,"production_lease_hash":a.ProductionLeaseHash,"production_gate_id":a.ProductionGateID,"health_snapshot_hash":a.ProductionHealthSnapshotHash,"cost_bound_hash":a.ProductionCostBoundHash,"cost_bound_minor":a.ProductionCostBoundMinor,"execution_mode":a.ExecutionMode,"idempotency_key":a.IdempotencyKey};b,e:=json.MarshalIndent(payload,"","  ");if e!=nil{return ProductionExecutionRecord{},"EXECUTION_FAILED"};f,e:=os.OpenFile(marker,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{return ProductionExecutionRecord{},"STOP_RECONCILIATION"};uncertain:=func(msg string)(ProductionExecutionRecord,string){_ = f.Close();state.Ledger.ReconciliationRequired=true;persistStickyStop(p,state,"RECONCILIATION_REQUIRED",ctx.Now);r:=productionExecutionRecord(*state,a,ctx.Now,"RECONCILIATION_REQUIRED","UNKNOWN",marker,msg);state.Execution=&r;return r,"STOP_RECONCILIATION"};if _,e=f.Write(b);e!=nil{return uncertain(e.Error())};if e=f.Sync();e!=nil{return uncertain(e.Error())};if e=f.Close();e!=nil{state.Ledger.ReconciliationRequired=true;persistStickyStop(p,state,"RECONCILIATION_REQUIRED",ctx.Now);r:=productionExecutionRecord(*state,a,ctx.Now,"RECONCILIATION_REQUIRED","UNKNOWN",marker,e.Error());state.Execution=&r;return r,"STOP_RECONCILIATION"};norm,ok:=normalizedProductionLedger(state.Ledger,state.Lease,now);if !ok{return uncertain("ledger invalid before update")};norm.ExecutionsTotal++;norm.ExecutionsInWindow++;norm.CostMinorTotal+=a.ProductionCostBoundMinor;norm.PendingOutcomes++;norm.PendingExecutionIDs=append(norm.PendingExecutionIDs,"exec-"+a.AuthorizationID);norm.SuccessfulIdempotencyKeys=append(norm.SuccessfulIdempotencyKeys,a.IdempotencyKey);norm.ConsecutiveFailures=0;norm.LastExecutionAt=ctx.Now;norm.UpdatedAt=ctx.Now;if e=persistProductionLedger(p,norm);e!=nil{state.Ledger.ReconciliationRequired=true;persistStickyStop(p,state,"RECONCILIATION_REQUIRED",ctx.Now);r:=productionExecutionRecord(*state,a,ctx.Now,"RECONCILIATION_REQUIRED","UNKNOWN",marker,"side effect written but ledger persistence failed");state.Execution=&r;return r,"STOP_RECONCILIATION"};state.Ledger=norm;r:=productionExecutionRecord(*state,a,ctx.Now,"SUCCEEDED","PERFORMED",marker,"");state.Execution=&r;return r,"EXECUTED"}
func RecordProductionOutcome(state *M11State,dir,outcomeID,executionID,observedAt string)string{if state==nil||strings.TrimSpace(outcomeID)==""||strings.TrimSpace(executionID)==""{return "DENY_OUTCOME"};lp:=productionLockPath(dir,state.Lease.LeaseID,state.Lease.LeaseVersion);lock,e:=os.OpenFile(lp,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{return "WAIT_PRODUCTION_LOCK"};_ = lock.Close();defer os.Remove(lp);p:=productionLedgerPath(dir,state.Lease.LeaseID,state.Lease.LeaseVersion);l,e:=loadProductionLedger(p);if e!=nil||l.ControlMode=="STOPPED"||l.ReconciliationRequired||l.PendingOutcomes<1{return "WAIT_RECONCILIATION"};for _,x:=range l.OutcomeLinks{if x.OutcomeID==outcomeID{return "DUPLICATE_OUTCOME"}};idx:=-1;for j,id:=range l.PendingExecutionIDs{if id==executionID{idx=j;break}};if idx<0{return "DENY_OUTCOME_LINK"};if _,e=time.Parse(time.RFC3339,observedAt);e!=nil{return "DENY_OUTCOME"};l.PendingExecutionIDs=append(l.PendingExecutionIDs[:idx],l.PendingExecutionIDs[idx+1:]...);l.PendingOutcomes--;l.OutcomeLinks=append(l.OutcomeLinks,ProductionOutcomeLink{OutcomeID:outcomeID,ExecutionID:executionID,ObservedAt:observedAt});l.ConsecutiveFailures=0;l.LastOutcomeAt=observedAt;l.UpdatedAt=observedAt;if e=persistProductionLedger(p,l);e!=nil{return "WAIT_RECONCILIATION"};state.Ledger=l;return "OUTCOME_RECORDED"}

func baseDemoM11()(M11State,M11Context){intent:=SealShadowActionIntent(ShadowActionIntent{IntentID:"i11",DecisionID:"d11",EvidenceIDs:[]string{"e11"},ActionType:"PREPARE_LOCAL_DRAFT",Target:"https://example.com/prod",Parameters:map[string]any{"title":"production"},ProposedBy:"human",CreatedAt:"2026-09-03T07:00:00Z",ExpiresAt:"2026-09-03T11:00:00Z",CorrelationID:"c11",IdempotencyKey:"k11"});pc:=ShadowPolicyContext{PolicyVersion:"m11-v1",Now:"2026-09-03T07:05:00Z",KnownDecisionIDs:[]string{"d11"},KnownEvidenceIDs:[]string{"e11"},AllowedHosts:[]string{"example.com"},ActionRisk:map[string]string{"PREPARE_LOCAL_DRAFT":"RISK0","UPDATE_DRAFT":"RISK1","PUBLISH_CONTENT":"RISK2"},SeenIdempotency:map[string]string{}};policy:=EvaluateShadowPolicy(intent,pc);lease:=SealProductionLease(ProductionLease{LeaseID:"lease11",LeaseVersion:"v1",PolicyVersion:"m11-v1",ApprovalRef:"prod-approval-11",ReviewedBy:"human",ReviewerID:"learner",ReviewedAt:"2026-09-03T07:10:00Z",PromotionReviewRef:"promotion-11",SourceCanaryGrantID:"g10",SourceCanaryGrantVersion:"v1",SourceCanaryGrantHash:"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",ValidFrom:"2026-09-03T07:15:00Z",ExpiresAt:"2026-09-03T10:00:00Z",AllowedRiskClasses:[]string{"RISK0"},AllowedActionTypes:[]string{"PREPARE_LOCAL_DRAFT"},AllowedHosts:[]string{"example.com"},ExecutorIDs:[]string{"local_sandbox"},MaxExecutionsTotal:10,MaxExecutionsPerWindow:2,WindowSeconds:3600,MaxCostMinorTotal:1000,Currency:"USD",MaxPendingOutcomes:1,MaxConsecutiveFailures:2,MaxOutcomeAgeSeconds:3600,MaxHealthSnapshotAgeSeconds:300,KillSwitchRequired:true,CorrelationID:"lease-c11"});health:=SealProductionHealth(ProductionHealthSnapshot{SnapshotID:"health11",LeaseID:lease.LeaseID,LeaseVersion:lease.LeaseVersion,LeaseHash:lease.LeaseHash,ObservedAt:"2026-09-03T07:59:00Z",SourceRefs:[]string{"otel:service","provider:status"},DependencyState:"HEALTHY",TelemetryComplete:true,HashVersion:"go-json-v1"});cost:=SealCanaryCostBound(CanaryCostBound{CostBoundID:"cost11",IntentID:intent.IntentID,IntentHash:intent.IntentHash,MaxCostMinor:10,Currency:"USD",SourceRef:"deterministic-cost-registry",ObservedAt:"2026-09-03T07:55:00Z",ExpiresAt:"2026-09-03T09:00:00Z",CorrelationID:intent.CorrelationID});ledger:=ProductionLedger{LeaseID:lease.LeaseID,LeaseVersion:lease.LeaseVersion,LeaseHash:lease.LeaseHash,ControlMode:"NORMAL",WindowStartedAt:"2026-09-03T07:15:00Z",UpdatedAt:"2026-09-03T07:15:00Z"};state:=M11State{Intent:intent,Policy:policy,Lease:lease,Health:health,CostBound:cost,Ledger:ledger};ctx:=M11Context{Now:"2026-09-03T08:00:00Z",ApprovedLeaseHashes:map[string]string{lease.ApprovalRef:lease.LeaseHash},PromotionValidatedRisks:map[string][]string{lease.PromotionReviewRef:{"RISK0"}},TrustedHealthSnapshots:map[string]string{health.SnapshotID:health.SnapshotHash},TrustedCostBounds:map[string]string{cost.CostBoundID:cost.CostBoundHash},Executor:ExecutorProfile{ExecutorID:"local_sandbox",AllowedActionTypes:[]string{"PREPARE_LOCAL_DRAFT"},AllowedHosts:[]string{"example.com"}},AllowedExecutorIDs:[]string{"local_sandbox"},PolicyContext:pc};return state,ctx}
func demoM11()(map[string]any,error){s,c:=baseDemoM11();a,g,status:=AuthorizeProduction(s,c);if status!="AUTHORIZED"{return nil,errors.New(status)};s.Authorization=&a;dir,e:=os.MkdirTemp("","m11-production-");if e!=nil{return nil,e};r,status:=ExecuteProductionLocalSandbox(&s,a,c,dir);if status!="EXECUTED"{return nil,errors.New(status)};return map[string]any{"gate":g,"authorization":a,"execution":r,"ledger":s.Ledger,"authority":"GOVERNED_PRODUCTION"},nil}
